"""Manual consolidation after reading all cote-8 passages and all 80 indexed notes.
No verdict is inferred from a heading, keyword, or an automatically detected cue.
The serialization helpers only expand locators and stable temporary identifiers.
"""
from pathlib import Path
from datetime import datetime, timezone
import csv,json
O=Path(__file__).resolve().parents[1]
P='MPL_7_061-072+8_001-078'; T='SA15_texts/pro/'+P+'_transcription.tex'
items=[];claims=[];problems=[];readings=[];entries=[];events=[];links=[]
now=datetime.now(timezone.utc).isoformat()
who='GPT-6 Astra Pro; effort not exposed; SA15-20261119/root'
def I(n,src,kind,scans,lines,words,statement,reconstruction,check,reason):
 x=dict(id=f'P78-I{n:03}',sources=[P+'#'+str(s) for s in src],kind=kind,cote=['8'],scans=['8:'+str(s).zfill(3) for s in scans],lines=[T+':'+lines],his_words=words,statement=statement,reconstruction=reconstruction,check=check,check_reason=reason)
 items.append(x);events.append([x['id'],now,who,'used and rechecked in this run','Textual comparison of the cited note and complete passage: '+check+'. '+reason])
def C(n,its,words,statement,status,cls,fate,refs,comp='',confidence='high'):
 src=[x for x in items if int(x['id'][-3:]) in its]
 x=dict(id=f'P78-C{n:03}',items=[f'P78-I{i:03}' for i in its],cote=['8'],scans=sorted({s for i in src for s in i['scans']}),lines=sorted({s for i in src for s in i['lines']}),his_statement=words,statement=statement,status_on_pages=status,computation=comp or 'No numerical calculation; see proof_audit_root.md for the explicit hypothesis/diagram check.',**{'class':cls},fate=fate,fate_date='Literature searched through 2026-11-19; first circulation and publication distinguished in reference_evidence.json.',present_status=fate,refs=refs,confidence=confidence)
 claims.append(x);events.append([x['id'],now,who,'used and rechecked in this run','Checked the precise supplied passage, its displayed hypotheses and proof status; compared the results at the reference locators. This is not a claim to have re-proved the whole cited theory.'])
def Pm(n,title,its,st,today,art,why,worth,refs):
 src=[x for x in items if int(x['id'][-3:]) in its]
 problems.append(dict(id=f'P78-P{n:03}',title=title,occurrences=[dict(cote='8',scans=i['scans'],lines=i['lines']) for i in src],as_he_states=st,plausible_today=today,state_of_art=art,why_open=why,worth=worth,refs=refs))
def R(scan,line,reading,alternative,evidence,weight='high',confidence='high mathematical alarm; ink undecided'):
 readings.append(dict(cote='8',scan=str(scan).zfill(3),line=T+':'+str(line),reading=reading,alternative=alternative,evidence=evidence,weight=weight,confidence=confidence))

